-- Search by comment: trigrams (pg_trgm) over a normalized copy.
--
-- Trigrams rather than full-text search: comments are short names
-- ("Пятёрочка", "Яндекс Такси") searched by a piece typed so far ("такс"),
-- which tsvector does not match (whole words only) and its stemmer has no
-- use for. A GIN index over trigrams serves LIKE '%…%'.
--
-- pg_trgm is a trusted extension (PostgreSQL 13+): the database owner may
-- create it, no superuser needed (managed Postgres included).
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- lower() with ё folded to е: "пятерочка" finds "Пятёрочка". Generated by
-- Postgres, so every write path (forms, imports, recurring payments, the
-- seed) gets it without knowing. lower() follows the database's LC_CTYPE:
-- it folds Cyrillic under a UTF-8 locale (en_US.utf8, C.UTF-8), not under C.
--
-- Adding a STORED column rewrites the table under an exclusive lock: fine
-- at this size. On a large live table: an expression index built
-- CONCURRENTLY (outside a transaction, so not in a Prisma migration), with
-- queries written against the same expression.
ALTER TABLE "transactions" ADD COLUMN "comment_search" TEXT
  GENERATED ALWAYS AS (lower(translate("comment", 'ёЁ', 'еЕ'))) STORED;

-- CreateIndex
CREATE INDEX "transactions_comment_search_idx" ON "transactions" USING GIN ("comment_search" gin_trgm_ops);
